import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double of the pricing dependency (strategy: inprocess).
const prices = { A: 10, B: 25, C: 60, D: 0.5 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order, total is the sum of price*qty', async () => {
  const r = await json(await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, { id: r.body.id, items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }], total: 45 })
  assert.equal(typeof r.body.id, 'string')
})

test('POST /orders ids are sequential strings', async () => {
  const a = await json(await post({ items: [{ sku: 'A', qty: 1 }] }))
  const b = await json(await post({ items: [{ sku: 'A', qty: 1 }] }))
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('POST /orders total of exactly 100 gets no discount', async () => {
  const r = await json(await post({ items: [{ sku: 'A', qty: 10 }] }))
  assert.equal(r.body.total, 100)
})

test('POST /orders total above 100 gets 10% discount', async () => {
  const r = await json(await post({ items: [{ sku: 'C', qty: 2 }] })) // 120 -> 108
  assert.equal(r.body.total, 108)
})

test('POST /orders total is floored (cents are dropped)', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — Math.floor drops fractional euros
  const r = await json(await post({ items: [{ sku: 'D', qty: 3 }] })) // 1.5 -> 1
  assert.equal(r.body.total, 1)
  const d = await json(await post({ items: [{ sku: 'B', qty: 5 }] })) // 125 -> 112.5 -> 112
  assert.equal(d.body.total, 112)
})

test('POST /orders asks pricing once per item line', async () => {
  calls.length = 0
  await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }] })
  assert.deepEqual(calls, ['A', 'A', 'B'])
})

test('POST /orders unknown sku / bad qty yields null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN is serialised as null, still 201
  const r = await json(await post({ items: [{ sku: 'ZZZ', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'x' }],
  ['empty body', undefined, ''],
  ['malformed JSON', undefined, '{nope'],
  ['JSON null', undefined, 'null'],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const r = await json(await post(body, raw))
    assert.equal(r.status, 400)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'items required' })
  })
}

test('GET /orders/{id} returns a created order', async () => {
  const c = await json(await post({ items: [{ sku: 'B', qty: 2 }] }))
  const r = await json(await fetch(`${base}/orders/${c.body.id}`))
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, c.body)
})

test('GET /orders/{id} unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const r = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

test('unmatched routes answer 404 {error:"no route"}', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/x'], ['GET', '/other']]) {
    const r = await json(await fetch(`${base}${path}`, { method }))
    assert.equal(r.status, 404, `${method} ${path}`)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'no route' })
  }
})
EOF
